import{_ as a,o as i,c as t,a3 as u,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/schueler/tutorials-bk-herkunft-eintragen.png",h="/bilder/schueler/tutorials-bk-herkunft-andere-schule.png",b=JSON.parse('{"title":"Die schulische Herkunft an BK und WBK erfassen","description":"","frontmatter":{"title":"Die schulische Herkunft an BK und WBK erfassen","source_pageid":310,"source_revision":3574},"headers":[],"relativePath":"schild3/schueler/eintragung-herkunft-am-bk-wbk-tutorial.md","filePath":"schild3/schueler/eintragung-herkunft-am-bk-wbk-tutorial.md"}'),s={name:"schild3/schueler/eintragung-herkunft-am-bk-wbk-tutorial.md"};function c(o,r,d,m,k,f){return i(),t("div",null,[...r[0]||(r[0]=[u('<h1 id="die-schulische-herkunft-an-bk-und-wbk-erfassen" tabindex="-1">Die schulische Herkunft an BK und WBK erfassen <a class="header-anchor" href="#die-schulische-herkunft-an-bk-und-wbk-erfassen" aria-label="Permalink to &quot;Die schulische Herkunft an BK und WBK erfassen&quot;">​</a></h1><p>Tragen Sie die zuvor besuchte Schule und die Herkunftsangaben ein. Unterscheiden Sie Schulen in NRW, Schulen außerhalb von NRW und eine unbekannte Herkunft.</p><p><a href="/bilder/schueler/tutorials-bk-herkunft-eintragen.png"><img src="'+l+'" alt="Tragen Sie die Herkunft von Schülern unter Schüler ➜ Schulbesuch ein." loading="lazy"></a></p><p><em>Tragen Sie die Herkunft von Schülern unter Schüler ➜ Schulbesuch ein.</em></p><h2 id="herkunft-unter-schulbesuch-eintragen" tabindex="-1">Herkunft unter Schulbesuch eintragen <a class="header-anchor" href="#herkunft-unter-schulbesuch-eintragen" aria-label="Permalink to &quot;Herkunft unter Schulbesuch eintragen&quot;">​</a></h2><p>Tragen Sie die Herkunft der Schüler mit den bekannten Daten unter <em>Schüler</em> ➜ <strong>Schulbesuch</strong> ein.</p><h2 id="schulen-aus-nrw" tabindex="-1">Schulen aus NRW <a class="header-anchor" href="#schulen-aus-nrw" aria-label="Permalink to &quot;Schulen aus NRW&quot;">​</a></h2><p>Wenn Sie eine Schule eintragen, wird die Schulnummer automatisch ausgefüllt.</p><p>Befindet sich eine Schule nicht im Dropdown-Menü zur Auswahl, lässt sich über das <strong>+</strong> neben dem Dropdown-Menü der Katalog mit den Schulnummern von Schulen in NRW öffnen.</p><p>Sie gelangen auf den Katalog, der auch über <em>Kataloge ➜ Schulen in NRW</em> zu erreichen ist. Diese Schulen stehen im Dropdown-Menü in Ihrem SchILD zur Verfügung.</p><p>Klicken Sie auch in diesem Katalog auf <strong>+</strong>. Suchen Sie die fehlende Schule über die Bezeichnung oder Schulnummer und fügen Sie sie dem Katalog hinzu. Anschließend können Sie die Schule unter <strong>Schulbesuch</strong> auswählen.</p><p>Wählen Sie die Schule in <strong>Schulbesuch</strong> an und tragen Sie die Daten ein.</p><p>Fügen Sie dann die Schule mit einem Klick auf den Rechtspfeil (➜) der Liste <em>Alle bisher besuchten Schulen</em> ein.</p><h2 id="schulen-außerhalb-von-nrw" tabindex="-1">Schulen außerhalb von NRW <a class="header-anchor" href="#schulen-außerhalb-von-nrw" aria-label="Permalink to &quot;Schulen außerhalb von NRW&quot;">​</a></h2><p><a href="/bilder/schueler/tutorials-bk-herkunft-andere-schule.png"><img src="'+h+'" alt="Schüler, die eine Herkunft außerhalb von NRW haben, werden über Sammel-Schulnummern erfasst." loading="lazy"></a></p><p><em>Schüler, die eine Herkunft außerhalb von NRW haben, werden über Sammel-Schulnummern erfasst.</em></p><p>Kommt ein Schüler aus einer Schule die nicht in NRW liegt, öffnen Sie <em>Kataloge ➜ Andere Schulen und Schulnummern</em> und fügen Sie einen passenden Eintrag in Ihre Kataloglist.</p><p>Zur Auswahl stehen hier die Bundesländer, <em>Schule aus den Niederlanden</em>, <em>Schule aus dem sonstigen Ausland</em> und <em>Sonstige/keine Schule</em>.</p><h2 id="unbekannte-herkunft" tabindex="-1">Unbekannte Herkunft <a class="header-anchor" href="#unbekannte-herkunft" aria-label="Permalink to &quot;Unbekannte Herkunft&quot;">​</a></h2><p>Die letzte Schulnummer kann auch für <em>unbekannte Herkunft</em> verwendet werden. Füllen Sie hierbei alle bekannten Daten aus und lassen Sie die Felder mit unbekannten Daten frei.</p>',20),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,"Da es sich nicht um viele Schulen/Schulnummern handelt, fügen Sie einmal alle dem Katalog hinzu. Dann stehen diese im Bedarfsfall direkt zur Verfügung.")],-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Wenn Sie die Schule "),e("em",null,"Sonstige/keine Schule"),n(" eintragen, lässt sich die Schule natürlich auch nicht mit dem Pfeil in die "),e("em",null,"bisher besuchten Schulen"),n(" verschieben.")])],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Eintragung_Herkunft_am_BK/WBK_(Tutorial)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 3574.")],-1)])])}const g=a(s,[["render",c]]);export{b as __pageData,g as default};
